        k("כדורסל סל נקודות משחק", "כדורסל הוא משחק קבוצתי שבו מנסים לקלוע את הכדור לסל של היריבה. קליעה רגילה שווה שתי נקודות, קליעה מעבר לקשת שלוש נקודות וקליעת עונשין נקודה אחת.", "בכל קבוצה נמצאים בדרך כלל חמישה שחקנים על המגרש בזמן משחק תקני.");
        k("בישול אורז מתכון", "כדי להכין אורז לבן פשוט, שוטפים כוס אורז, מוסיפים בדרך כלל כשתי כוסות מים ומעט מלח, מביאים לרתיחה ומבשלים מכוסה על אש נמוכה עד שהמים נספגים.", "יחס המים וזמן הבישול משתנים לפי סוג האורז והסיר. כדאי לבדוק את הוראות האריזה.");
        k("בישול ביצה ביצים", "אפשר לבשל ביצה במים רותחים. זמן הבישול משפיע על המרקם: קצר יותר לחלמון רך וארוך יותר לחלמון מוצק.", "קירור הביצה לאחר הבישול עוצר את המשך הבישול ועשוי להקל על הקילוף.");
        k("לחם שמרים אפייה בצק", "לחם בסיסי מורכב בדרך כלל מקמח, מים, שמרים ומלח. השמרים מתסיסים סוכרים ומשחררים פחמן דו־חמצני שיוצר בועות בבצק.", "לישה, התפחה ואפייה משפיעות על המרקם והטעם. סוג הקמח וכמות המים משנים את התוצאה.");
        k("טיול הכנה מסלול מים ציוד", "לתכנון טיול כדאי לבדוק אורך מסלול, מזג אוויר, קושי, זמני הליכה, נקודות מים וציוד מתאים.", "כדאי לעדכן אדם נוסף על המסלול, לקחת מים בכמות מספקת ולהימנע ממסלול שאינו מתאים ליכולת או לתנאי השטח.");
        k("מוזיקה צליל קצב מנגינה", "מוזיקה משלבת צלילים, קצב, מלודיה והרמוניה. תרבויות שונות פיתחו סגנונות וכלים מגוונים.", "קצב מתאר את ארגון הפעימות בזמן, ומלודיה היא רצף צלילים שנתפס כמנגינה.");
        k("פסנתר קלידים תווים כלי נגינה", "פסנתר הוא כלי מקלדת שבו לחיצה על קליד מפעילה מנגנון שמכה במיתר באמצעות פטיש קטן.", "בפסנתר מודרני יש בדרך כלל 88 קלידים, והצליל נוצר מרטט המיתרים שמוגבר באמצעות לוח התהודה.");
        k("גיטרה מיתרים אקורדים כלי נגינה", "גיטרה היא כלי מיתר שמפיק צליל מפריטת המיתרים או משיכתם. אפשר לנגן בה מנגינות ואקורדים.", "אקורד הוא שילוב של כמה צלילים שנשמעים יחד. כיוון המיתרים משפיע על הצליל והנגינה.");

        k("מערכת השמש כוכבי לכת חמה נוגה מאדים צדק שבתאי אורנוס נפטון", "במערכת השמש יש שמונה כוכבי לכת שמקיפים את השמש: חמה, נוגה, כדור הארץ, מאדים, צדק, שבתאי, אורנוס ונפטון.", "פלוטו מוגדר כיום ככוכב לכת ננסי. כוכבי הלכת שונים בגודל, בהרכב ובמרחק שלהם מהשמש.");
        k("מאדים כוכב לכת אדום חלל", "מאדים מכונה לעיתים הכוכב האדום בגלל תחמוצות ברזל באדמתו. יש בו הרי געש גדולים, עמקים וסימנים לכך שבעבר זרמו בו מים.", "רוברים וחלליות מחקר ביקרו במאדים כדי לחקור את הקרקע, האטמוספרה והאפשרות לתנאים קדומים שתמכו בחיים.");
        k("צדק כוכב לכת גדול כתם אדום", "צדק הוא כוכב הלכת הגדול ביותר במערכת השמש. הוא ענק גזים ובאטמוספרה שלו נמצאת הסופה הגדולה המכונה הכתם האדום הגדול.", "לצדק יש ירחים רבים, ובהם אירופה, גנימד, קליסטו ואיו.");
        k("שבתאי טבעות כוכב לכת", "שבתאי הוא ענק גזים שמוכר בזכות מערכת הטבעות הבולטת שלו. הטבעות מורכבות בעיקר מחלקיקי קרח, אבק וסלע.", "גם לכוכבי לכת אחרים יש טבעות, אך אלה של שבתאי בולטות במיוחד.");
        k("גלקסיה שביל החלב כוכבים מערכת שמש", "שביל החלב היא הגלקסיה שבה נמצאת מערכת השמש. היא מכילה מאות מיליארדי כוכבים, גז ואבק הקשורים בכוח הכבידה.", "בלילה חשוך במיוחד אפשר לראות חלק מהגלקסיה כרצועת אור חלשה בשמים.");
        k("חור שחור כבידה אור חלל", "חור שחור הוא אזור בחלל שבו הכבידה חזקה כל כך שמעבר לגבול מסוים, הנקרא אופק האירועים, אפילו אור אינו יכול להימלט החוצה.", "מדענים מזהים חורים שחורים לפי השפעתם על חומר ואור בסביבתם ולפי גלי כבידה מאירועים מסוימים.");
        k("כוכב ננס לבן סופרנובה חיים של כוכב", "כוכבים נוצרים מענני גז ואבק, ובמהלך חייהם מפיקים אנרגיה בתהליכים גרעיניים. סיום חייהם תלוי בעיקר במסה שלהם.", "כוכבים מסיביים עשויים לסיים את חייהם בפיצוץ סופרנובה, ואילו כוכבים דמויי שמש צפויים להפוך לננסים לבנים.");
        k("מהירות הקול קול אוויר טמפרטורה", "באוויר בטמפרטורת חדר מהירות הקול היא בערך 343 מטר לשנייה. היא משתנה בהתאם לטמפרטורה ולחומר שבו הקול מתפשט.", "במים ובחומרים מוצקים הקול מתפשט במהירויות אחרות, בדרך כלל גבוהות יותר מאשר באוויר.");
        k("חיכוך כוח תנועה משטח", "חיכוך הוא כוח שמתנגד לתנועה יחסית בין משטחים שנוגעים זה בזה. הוא יכול להאט גוף נע וגם לאפשר הליכה ואחיזה.", "חיכוך יוצר לעיתים חום. שמן וסיכה מפחיתים חיכוך בין חלקים נעים במכונות.");
        k("ניוטון חוקי התנועה כוח מסה תאוצה", "חוקי התנועה של ניוטון מתארים קשרים בין כוח, מסה ותנועה. החוק השני נכתב לעיתים F=ma: כוח שווה מסה כפול תאוצה.", "החוקים מסבירים מצבים רבים, מתנועת מכונית ועד מסלולי חלליות, כאשר מתחשבים בכוחות שפועלים על הגוף.");
        k("צפיפות מסה נפח חומר", "צפיפות היא המסה ליחידת נפח. חומר צפוף יותר מכיל יותר מסה באותו נפח.", "צפיפות יכולה לעזור להסביר מדוע חומרים מסוימים שוקעים במים ואחרים צפים, בהתאם גם לצפיפות הנוזל.");
        k("חלודה ברזל חמצן מים קורוזיה", "חלודה נוצרת כאשר ברזל מגיב עם חמצן ומים ונוצרים תחמוצות ברזל. התהליך נקרא קורוזיה.", "צבע, ציפוי, שמן או שימוש בחומרים עמידים יכולים להאט חלודה במקומות מתאימים.");
        k("פלסטיק פולימר חומר מלאכותי", "פלסטיק הוא שם כללי לקבוצת חומרים שמבוססים על פולימרים. אפשר לייצר פלסטיקים בעלי תכונות שונות כמו גמישות, קשיחות ושקיפות.", "מיון ומחזור פלסטיק תלויים בסוג החומר ובמערכות האיסוף המקומיות.");
        k("זכוכית חול חימום חומר", "זכוכית נפוצה מיוצרת בעיקר מסיליקה, שמקורה לעיתים בחול, יחד עם חומרים נוספים. מחממים את התערובת לטמפרטורה גבוהה ומעצבים אותה.", "זכוכית אינה גביש מסודר כמו מלח או קוורץ גבישי; המבנה שלה אמורפי.");
        k("מתכת מוליכות חשמל חום", "מתכות רבות מוליכות היטב חשמל וחום, ניתנות לעיבוד ובעלות ברק אופייני. דוגמאות הן נחושת, אלומיניום וברזל.", "הולכה חשמלית טובה של נחושת הופכת אותה לחומר נפוץ בחוטי חשמל.");
        k("טרנזיסטור אלקטרוניקה מתג מגבר", "טרנזיסטור הוא רכיב אלקטרוני שיכול לשמש כמתג או כמגבר של אות. מיליארדי טרנזיסטורים משולבים במעבדים מודרניים.", "היכולת לשלוט בזרם חשמלי באמצעות אות קטן היא אחת מאבני היסוד של האלקטרוניקה.");
        k("דיודה רכיב אלקטרוני זרם כיוון", "דיודה היא רכיב אלקטרוני שמאפשר לזרם לעבור בקלות יחסית בכיוון אחד ומגביל אותו בכיוון ההפוך, בהתאם לסוג הדיודה ולתנאי העבודה.", "נורית LED היא סוג של דיודה שפולטת אור כאשר זרם מתאים זורם דרכה.");
        k("מסך LCD LED OLED תצוגה", "מסכי LCD משתמשים בגבישים נוזליים ובמערכת תאורה אחורית. במסכי OLED כל פיקסל יכול לפלוט אור בעצמו.", "סוג המסך משפיע על ניגודיות, בהירות, צריכת חשמל, עובי ועלות.");
        k("רזולוציה פיקסלים מסך תמונה", "רזולוציה מתארת כמה נקודות תמונה, פיקסלים, יש בתצוגה או בתמונה. רזולוציה גבוהה יותר יכולה להציג פרטים רבים יותר באותו גודל.", "חדות התמונה תלויה גם בצפיפות הפיקסלים, בגודל המסך ובמרחק הצפייה.");
        k("קובץ פורמט סיומת תמונה שמע", "סיומת קובץ מרמזת על סוג התוכן או הפורמט שלו, למשל JPG לתמונה, MP3 לשמע ו-PDF למסמך.", "שינוי שם הסיומת לבדו אינו ממיר את תוכן הקובץ. כדי להמיר פורמט צריך להשתמש בתוכנה מתאימה.");
        k("דחיסה zip קובץ קטן ארכיון", "דחיסת קבצים מקטינה את נפח האחסון או מאגדת כמה קבצים לארכיון אחד. ZIP הוא פורמט נפוץ לארכיונים דחוסים.", "חלק מהקבצים כבר דחוסים ולכן לא תמיד ניתן להקטין אותם בהרבה.");
        k("ענן אחסון ענן שרתים אינטרנט", "אחסון בענן שומר קבצים בשרתים מרוחקים שמגיעים אליהם דרך רשת. הוא מאפשר גישה ממספר מכשירים, בהתאם להרשאות ולחיבור.", "שירות ענן אינו קסם: הנתונים נשמרים במרכזי נתונים, ויש לבדוק אבטחה, גיבוי ותנאי שימוש.");
        k("דפדפן chrome firefox אתר אינטרנט", "דפדפן הוא יישום שמציג אתרי אינטרנט ומאפשר לעבור בין דפים, להוריד קבצים ולהריץ קוד אתר.", "Chrome, Firefox ו-Safari הם דוגמאות לדפדפנים. כדאי לעדכן דפדפן כדי לקבל תיקוני אבטחה.");
        k("כתובת IP רשת מחשב", "כתובת IP מזהה ממשק ברשת כדי לאפשר העברת חבילות נתונים אליו. קיימות גרסאות IPv4 ו-IPv6.", "כתובת IP אינה בהכרח מזהה אדם או כתובת בית מדויקת; היא יכולה להשתנות ולהיות משותפת באמצעות נתבים.");
        k("DNS דומיין שם מתחם כתובת אתר", "DNS הוא שירות שמתרגם שמות מתחם, כמו example.com, לכתובות IP שמחשבים משתמשים בהן כדי להגיע לשרתים.", "אפשר לחשוב עליו כמו ספר טלפונים של האינטרנט, אף שבפועל מערכת DNS מבוזרת ומורכבת יותר.");
        k("HTTP HTTPS הצפנה אתר", "HTTP הוא פרוטוקול להעברת מידע בין דפדפן לשרת. HTTPS מוסיף הצפנה ואימות באמצעות TLS.", "סמל מנעול בדפדפן מציין בדרך כלל חיבור מוצפן, אך אינו מבטיח שהאתר עצמו אמין או שהמידע בו נכון.");
        k("דואר אלקטרוני email הודעה", "דואר אלקטרוני מאפשר לשלוח ולקבל הודעות דרך רשת. כתובת דוא״ל מורכבת בדרך כלל משם משתמש, סימן @ ושם מתחם.", "כדאי להיזהר מקבצים מצורפים והודעות מתחזות, במיוחד כאשר מבקשים פרטים אישיים או תשלום.");
        k("גיבוי שחזור קבצים עותק", "גיבוי הוא שמירת עותק נוסף של מידע כדי לשחזר אותו במקרה של מחיקה, תקלה או אובדן המכשיר.", "גיבוי טוב נשמר בנפרד מהעותק המקורי ונבדק מדי פעם כדי לוודא שאפשר לשחזר ממנו.");
        k("מערכת בינארית אפס אחד ביט בית", "מחשבים מייצגים מידע באמצעות ספרות בינאריות: 0 ו-1. ביט הוא ספרה בינארית אחת, ובית מורכב בדרך כלל משמונה ביטים.", "תמונות, טקסט, צלילים ותוכניות נשמרים בסופו של דבר כרצפים של ביטים.");
        k("שפת מכונה בינארי מעבד פקודות", "שפת מכונה היא אוסף פקודות ברמה נמוכה שהמעבד מסוגל לבצע ישירות. שפות תכנות גבוהות מתורגמות או מתקמפלות לייצוג שהמחשב יכול להריץ.", "אסמבלי מציג פקודות מכונה בצורה קריאה יותר לאדם, אך עדיין קרוב מאוד לחומרה.");
        k("משתנה תכנות ערך זיכרון", "משתנה בתוכנית הוא שם שמייצג ערך שניתן להשתמש בו ולעיתים לשנות אותו במהלך הריצה.", "לדוגמה, משתנה בשם score יכול לשמור את מספר הנקודות במשחק.");
        k("לולאה תכנות חזרה for while", "לולאה היא מבנה תכנות שמבצע פעולה שוב ושוב כל עוד מתקיים תנאי או במשך מספר חזרות מוגדר.", "חשוב לוודא שתנאי העצירה יכול להתקיים כדי לא ליצור לולאה אינסופית.");
        k("תנאי if else תכנות בחירה", "תנאי בתוכנית מאפשר לבחור בין פעולות לפי מצב. ב-if בודקים תנאי, ואם הוא מתקיים מריצים בלוק מסוים, ואפשר להוסיף else למקרה האחר.", "תנאים מאפשרים לתוכנית להגיב לקלט, לשגיאות ולמצבים שונים.");
        k("פונקציה תכנות מתודה פרמטר", "פונקציה היא יחידת קוד שמבצעת משימה מוגדרת. היא יכולה לקבל פרמטרים ולהחזיר תוצאה.", "חלוקה לפונקציות עוזרת לארגן קוד, לצמצם כפילויות ולבדוק חלקים בנפרד.");
        k("באג שגיאה תוכנה איתור תקלה", "באג הוא פגם בתוכנה שגורם להתנהגות שגויה או לא צפויה. איתור באגים כולל שחזור התקלה, בדיקת הודעות שגיאה ובחינת הקוד.", "כדאי לשנות דבר אחד בכל פעם ולבדוק שוב כדי להבין איזה שינוי פתר או גרם לתקלה.");
        k("קוד פתוח open source רישיון תוכנה", "תוכנת קוד פתוח מפרסמת את קוד המקור שלה תחת רישיון שמאפשר שימושים ושינויים בהתאם לתנאיו.", "קוד פתוח אינו אומר שאין זכויות יוצרים. חשוב לקרוא את הרישיון לפני העתקה או הפצה.");
        k("תמונה פיקסל צבע RGB אדום ירוק כחול", "במסכי מחשב רבים צבע נוצר משילוב אור אדום, ירוק וכחול, שיטה שנקראת RGB.", "ערכים שונים של שלושת ערוצי הצבע יוצרים גוונים רבים. בשילוב מלא של שלושתם מתקבל לבן במסך.");
        k("GPS ניווט לוויינים מיקום", "GPS הוא מערכת ניווט לוויינית שמאפשרת למקלט לחשב מיקום וזמן על בסיס אותות מכמה לוויינים.", "הדיוק מושפע מתנאי השמים, חסימות, איכות המקלט ומערכות תיקון נוספות.");
        k("מצפן צפון דרום כיוון מגנטי", "מצפן מגנטי מכיל מחט שמסתדרת בקירוב עם השדה המגנטי של כדור הארץ ומסייעת לזהות כיוון.", "הצפון המגנטי אינו זהה בדיוק לצפון הגאוגרפי, וההפרש משתנה לפי המקום והזמן.");
        k("מפה קנה מידה מרחק גאוגרפיה", "מפה היא ייצוג מוקטן של אזור. קנה מידה מציין את היחס בין מרחק במפה למרחק במציאות.", "חשוב לבדוק את המקרא, סימני הכיוונים וקנה המידה כדי לקרוא מפה נכון.");
        k("שפה שם עצם פועל תואר דקדוק", "שם עצם מציין אדם, מקום, דבר או רעיון; פועל מציין פעולה או מצב; ושם תואר מתאר תכונה של שם עצם.", "במשפט 'הילד קורא ספר מעניין' — ילד וספר הם שמות עצם, קורא הוא פועל ומעניין הוא שם תואר.");
        k("עברית אותיות סופיות ך ם ן ף ץ", "בעברית יש חמש אותיות שמקבלות צורה מיוחדת בסוף מילה: כ הופכת ל-ך, מ ל-ם, נ ל-ן, פ ל-ף וצ ל-ץ.", "הצורה הסופית מופיעה בסוף מילה גם כאשר מצטרפות אליה סיומות מסוימות.");
